import{_ as n,a0 as s,w as i,s as c,ao as h,I as o,x as t,a1 as r,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Linux常見問題與答案—如何在Apache網站服務器上關閉服務器簽名 | LCTT x X-CMD","titleTemplate":false,"description":"Linux常見問題與答案—如何在Apache網站服務器上關閉服務器簽名 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux常見問題與答案—如何在Apache網站服務器上關閉服務器簽名 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux常見問題與答案—如何在Apache網站服務器上關閉服務器簽名 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140813 Linux FAQs with Answers--How to turn off server signature on Apache web server","title":"Linux常見問題與答案—如何在Apache網站服務器上關閉服務器簽名","tag":"201408","desc":""},"relativePath":"201408/20140813 Linux FAQs with Answers--How to turn off server signature on Apache web server.md","filePath":"[post].md"}'),u={name:"201408/20140813 Linux FAQs with Answers--How to turn off server signature on Apache web server.md"};function l(d,e,f,m,A,x){const p=s("Link");return i(),c("div",null,[e[11]||(e[11]=h(`<h1 id="linux常見問題與答案—如何在apache網站服務器上關閉服務器簽名" tabindex="-1">Linux常見問題與答案—如何在Apache網站服務器上關閉服務器簽名 <a class="header-anchor" href="#linux常見問題與答案—如何在apache網站服務器上關閉服務器簽名" aria-label="Permalink to “Linux常見問題與答案—如何在Apache網站服務器上關閉服務器簽名”">​</a></h1><blockquote><p><strong>問題</strong>：每當Apache2網站服務器返回錯誤頁時（如，404 頁面無法找到，403 禁止訪問頁面），它會在頁面底部顯示網站服務器簽名（如，Apache版本號和操作系統信息）。同時，當Apache2網站服務器為PHP頁面服務時，它也會顯示PHP的版本信息。我如何在Apache2網站服務器上關閉這些網站服務器簽名呢？</p></blockquote><p>透露網站服務器帶有服務器/PHP版本信息的簽名會帶來安全隱患，因為你基本上將你係統上的已知漏洞告訴給了攻擊者。因此，作為服務器加固的一個部分，強烈推薦你禁用所有網站服務器簽名。</p><p><img src="https://farm4.staticflickr.com/3897/14902970545_c3d406322f_o.png" alt=""></p><h3 id="禁用apache網站服務器簽名" tabindex="-1">禁用Apache網站服務器簽名 <a class="header-anchor" href="#禁用apache網站服務器簽名" aria-label="Permalink to “禁用Apache網站服務器簽名”">​</a></h3><p>禁用Apache網站服務器簽名可以通過編輯Apache配置文件來實現。</p><p>在Debian，Ubunt或者Linux Mint上：</p><pre><code>$ sudo vi /etc/apache2/apache2.conf
</code></pre><p>在CentOS，Fedora，RHEL或者Arch Linux上：</p><pre><code>$ sudo vi /etc/httpd/conf/httpd.conf
</code></pre><p>將下面兩行添加到Apache配置文件底部。</p><blockquote><p>ServerSignature Off</p><p>ServerTokens Prod</p></blockquote><p>然後重啓網站服務器以使修改生效：</p><pre><code>$ sudo service apache2 restart (Debian, Ubuntu or Linux Mint)
$ sudo service httpd restart (CentOS/RHEL 6)
$ sudo systemctl restart httpd.service (Fedora, CentOS/RHEL 7, Arch Linux)
</code></pre><p>第一行‘ServerSignature Off’使得Apache2網站服務器在所有錯誤頁面上隱藏Apache版本信息。</p><p><img src="https://farm6.staticflickr.com/5556/14879982016_7c7b8bbf3d_o.png" alt=""></p><p>然而，若沒有第二行的‘ServerTokens Prod’，Apache服務器將仍然在HTTP回應頭部包含詳細的服務器標記，這會泄漏Apache的版本號。</p><p><img src="https://farm4.staticflickr.com/3889/14902970535_e84ec23090_z.jpg" alt=""></p><p>第二行‘<strong>ServerTokens Prod</strong>’所要做的是在HTTP響應頭中將服務器標記壓縮到最小。</p><p>因此，同時放置兩行時，Apache將不會在頁面中或者HTTP響應頭中泄漏版本信息。</p><p><img src="https://farm4.staticflickr.com/3902/14902970505_d79225f25d_z.jpg" alt=""></p><h3 id="隱藏php版本" tabindex="-1">隱藏PHP版本 <a class="header-anchor" href="#隱藏php版本" aria-label="Permalink to “隱藏PHP版本”">​</a></h3><p>另外一個潛在的安全威脅是HTTP響應頭中的PHP版本信息泄漏。默認情況下，Apache網站服務器通過HTTP響應頭中的“X-Powered-By”字段包含有PHP版本信息。如果你想要在HTTP頭部中隱藏PHP版本，請使用文本編輯器打開php.ini文件，找到“expose_php = On”這一行，將它改為“expose_php = Off”即可。</p><p><img src="https://farm4.staticflickr.com/3853/14899917981_aaef71eb0a.jpg" alt=""></p><p>在Debian，Ubunt或者Linux Mint上：</p><pre><code>$ sudo vi /etc/php5/apache2/php.ini
</code></pre><p>在CentOS，Fedora，RHEL或者Arch Linux上：</p><pre><code>$ sudo vi /etc/php.ini
</code></pre><blockquote><p>expose_php = Off</p></blockquote><p>最後，重啓Apache2網站服務器來重新加載已更新的PHP配置文件。</p><p>現在，你不會再看到帶有“X-Powered-By”字段的HTTP響應頭了。</p><hr>`,32)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),r(p,{href:"http://ask.xmodulo.com/turn-off-server-signature-apache-web-server.html"},{default:a(()=>[...e[0]||(e[0]=[t("http://ask.xmodulo.com/turn-off-server-signature-apache-web-server.html",-1)])]),_:1})]),o("p",null,[e[4]||(e[4]=t("譯者：",-1)),r(p,{href:"https://github.com/GOLinux"},{default:a(()=>[...e[2]||(e[2]=[t("GOLinux",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),r(p,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...e[3]||(e[3]=[t("Caroline",-1)])]),_:1})]),o("p",null,[e[8]||(e[8]=t("本文由 ",-1)),r(p,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),r(p,{href:"http://linux.cn/"},{default:a(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const _=n(u,[["render",l]]);export{L as __pageData,_ as default};
